/**
 * Passage 1: the first wash, wet into wet over the whole sheet.
 *
 * A rainy avenue at dusk, seen from a little above the street: the buildings close in
 * on both sides, the sky is a glowing slot at the far end, and the wet road mirrors it.
 * This passage lays the lightest tones everywhere at once, the way a watercolorist
 * floods the sheet: warm glow at the far end of the avenue and down the middle of the
 * road, cooling to blue-grey at the top and the edges. The brightest lights (lamp
 * heads, headlights, the steam, the crosswalk) are saved by lifting the brush off the
 * paper around them, so they stay the paper's own white. While the wash is still wet,
 * a few bold drops of rose, gold, and blue go into it to bloom where they land, and a
 * little warm color is dropped in around each lamp head for its halo.
 */

// The tubes. Every other color is mixed from these, and lightened with water, never white.
palette('water', '#f3efe6');
palette('gamboge', '#f2b51a');
palette('scarlet', '#d8381f');
palette('crimson', '#8c1c34');
palette('ultra', '#24308e');
palette('payne', '#2f3a48');
palette('sienna', '#8b4522');
palette('ochre', '#c99a3e');
palette('cerulean', '#3f8fc0');

// Piles for the first wash, from the hot glow at the end of the avenue to the cool top.
palette('glowHot', mix(['gamboge', 1], ['ochre', 0.6], ['water', 7]));
palette('glow', mix(['ochre', 1], ['crimson', 0.18], ['water', 7]));
palette('skyRose', mix(['crimson', 0.5], ['payne', 0.5], ['ochre', 0.3], ['water', 8]));
palette('skyGrey', mix(['payne', 1], ['crimson', 0.2], ['water', 6]));
palette('skyCool', mix(['payne', 1], ['ultra', 0.3], ['water', 4]));
// The warm drop for the lamps' halos.
palette('lampWarm', mix(['gamboge', 2], ['scarlet', 0.35], ['water', 3]));

const W = canvas.width;
const H = canvas.height;

/**
 * The view: eye 5 m above the road, looking up the avenue. A point X metres right of
 * the avenue's middle, D metres away and Z metres up lands at (sx, sy).
 */
const VP = { x: 630, y: 780 };
const EYE = 5;
const F = 1000;
const sx = (X, D) => VP.x + (X * F) / D;
const sy = (Z, D) => VP.y + ((EYE - Z) * F) / D;
const clamp01 = (v) => Math.min(1, Math.max(0, v));

/** The lamps: head positions (the arm reaches over the road from the curb). */
const LAMPS = [
  { X: -3.6, D: 8 },
  { X: 3.5, D: 15 },
  { X: -3.6, D: 38 },
  { X: 3.5, D: 46 },
  { X: -3.6, D: 70 },
  { X: 3.5, D: 85 },
  { X: -3.6, D: 120 },
  { X: 3.5, D: 150 },
].map((l) => ({ x: sx(l.X, l.D), y: sy(7.5, l.D), r: (0.35 * F) / l.D, gy: sy(0, l.D) }));

/** Headlights coming toward us: the cab, the bus, and pairs far up the avenue. */
const HEADLIGHTS = [
  { X: -3.1, D: 24 },
  { X: -1.7, D: 24 },
  { X: -3.6, D: 60 },
  { X: -1.6, D: 60 },
  { X: -2.9, D: 110 },
  { X: -1.8, D: 110 },
  { X: -3.2, D: 190 },
  { X: -2.2, D: 190 },
].map((h) => ({
  x: sx(h.X, h.D),
  y: sy(0.65, h.D),
  r: Math.max(2, (0.22 * F) / h.D),
  gy: sy(0, h.D),
}));

/** The steam from the stack in the road: how dense it is at a point, 0–1. */
const STACK = { x: sx(-3, 13), y: sy(2.4, 13) };
function steam(x, y) {
  const t = (STACK.y - y) / 420; // 0 at the stack's mouth, 1 high up
  if (t < -0.02 || t > 1.15) return 0;
  const u = Math.max(0, t);
  const cx = STACK.x - 150 * u ** 1.3 + 22 * noise(u * 3, 4.1);
  const half = 14 + 120 * u ** 0.8;
  const d = Math.abs(x - cx) / half;
  const n = 0.75 + 0.35 * noise(x / 40, y / 55);
  return clamp01((1 - d * d) * n * (1 - clamp01((t - 0.55) / 0.6)) * 1.25);
}

/** The crosswalk: pale stripes running up the avenue, between D 7 and 8.6. */
function crosswalk(x, y) {
  if (y <= VP.y) return 0;
  const D = (EYE * F) / (y - VP.y);
  if (D < 7 || D > 8.6) return 0;
  const X = ((x - VP.x) * D) / F;
  if (X < -4.5 || X > 4.4) return 0;
  return (X + 10) % 1.1 < 0.6 ? 1 : 0;
}

/**
 * How strongly the brush should spare a point: 1 keeps the paper bare. `margin` is how
 * far around a light the brush starts to lift, about half its width.
 */
function reserve(x, y, margin) {
  let s = 0;
  for (const l of LAMPS) {
    const d = Math.hypot(x - l.x, (y - l.y) * 1.4) - l.r;
    s = Math.max(s, clamp01(1 - d / margin));
    // its reflection runs straight down the wet road
    const ry = l.gy + (l.gy - l.y);
    if (y > l.gy) {
      const dr =
        Math.hypot(
          (x - l.x) * 2.2,
          Math.max(0, Math.abs(y - (l.gy + ry) / 2) - (ry - l.gy) / 2) * 0.5,
        ) - l.r;
      s = Math.max(s, 0.8 * clamp01(1 - dr / margin));
    }
  }
  for (const h of HEADLIGHTS) {
    const d = Math.hypot(x - h.x, y - h.y) - h.r;
    s = Math.max(s, clamp01(1 - d / margin));
    // its reflection: a long streak from the road under it toward us
    if (y > h.gy) {
      const len = (h.gy - h.y) * 6;
      const dr = Math.hypot((x - h.x) * 2.5, Math.max(0, y - h.gy - len) * 0.4) - h.r * 0.8;
      s = Math.max(s, 0.85 * clamp01(1 - dr / margin));
    }
  }
  s = Math.max(s, steam(x, y));
  s = Math.max(s, 0.55 * crosswalk(x, y));
  return s;
}

/**
 * A stroke path from (x0, y0) to (x1, y1) with a little sag, resampled every 6 px, its
 * pressure eased off wherever reserve() asks the paper to stay bare.
 */
function spared(x0, y0, x1, y1, base, margin) {
  const n = Math.max(2, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 6));
  const sag = rand(-6, 6);
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = x0 + (x1 - x0) * t;
    const y = y0 + (y1 - y0) * t + sag * Math.sin(Math.PI * t);
    pts.push([x, y, base * (1 - reserve(x, y, margin))]);
  }
  return pts;
}

/**
 * Which pile a level band takes at height y: in the middle of the avenue the sky slot
 * and its reflection in the road (hot glow at the far end, cooling away from it); out
 * at the sides the walls and pavements, a plain cool grey.
 */
function middlePile(y) {
  if (y < 260) return 'skyCool';
  if (y < 520) return 'skyRose';
  if (y < 700) return 'glow';
  if (y < 1010) return 'glowHot';
  if (y < 1320) return 'glow';
  return 'skyRose';
}
/** Half the width of the middle band at height y: the sky slot, and the glow's column in the road. */
const middleHalf = (y) => (y < VP.y ? 190 - (VP.y - y) * 0.02 : 70 + (y - VP.y) * 0.34);

brush('flood', { type: 'soft', width: 110, reservoir: 8 });
brush('floodSmall', { type: 'soft', width: 50, reservoir: 6 });

// The flood: overlapping level bands from the top down, each in three strokes (side,
// middle, side) that run into each other wet at their seams. Where a light is near,
// a smaller brush works in closer to it.
for (let y = -20; y < H + 40; y += 26) {
  const half = middleHalf(y) * rand(0.9, 1.1);
  const xl = VP.x - half;
  const xr = VP.x + half;
  const bands = [
    [-90, xl + 50, y < VP.y + 20 ? 'skyGrey' : 'skyCool'],
    [xl - 50, xr + 50, middlePile(y + rand(-30, 30))],
    [xr - 50, W + 90, y < VP.y + 20 ? 'skyGrey' : 'skyCool'],
  ];
  for (const [x0, x1, pile] of bands) {
    const near = reserve((x0 + x1) / 2, y, 60) > 0.02 || y > 1330;
    stroke({
      path: spared(x0, y + rand(-6, 6), x1, y + rand(-6, 6), rand(0.62, 0.75), near ? 24 : 46),
      brush: near ? 'floodSmall' : 'flood',
      color: pile,
      paint: 'transparent',
      thinner: 0.62,
      load: 0.85,
    });
  }
}

// A few bold drops of color into the wet flood, left to bloom where they land: rose and
// gold at the far end of the avenue, a cool blue high in the sky slot, a warm one
// down the road where the glow is reflected.
palette('dropRose', mix(['crimson', 1], ['scarlet', 0.3], ['water', 2]));
palette('dropGold', mix(['gamboge', 1], ['scarlet', 0.15], ['water', 1.5]));
palette('dropBlue', mix(['cerulean', 1], ['ultra', 0.3], ['water', 2]));
for (const [x, y, w, pile] of [
  [610, 600, 70, 'dropRose'],
  [680, 690, 60, 'dropGold'],
  [560, 120, 90, 'dropBlue'],
  [720, 260, 70, 'dropBlue'],
  [640, 1060, 80, 'dropGold'],
  [600, 1280, 70, 'dropRose'],
]) {
  stroke({
    path: [
      [x + rand(-8, 8), y + rand(-8, 8), 0.7 * (1 - reserve(x, y, 20))],
      [x + rand(-14, 14), y + rand(14, 26), 0.6 * (1 - reserve(x, y + 20, 20))],
    ],
    brush: { type: 'soft', width: w },
    color: pile,
    paint: 'transparent',
    thinner: 0.62,
    load: 0.85,
  });
}

// Warm drops into the wet wash: a small halo around each lamp head.
for (const l of LAMPS) {
  for (let k = 0; k < 3; k++) {
    const a = rand(Math.PI * 2);
    const r = l.r * rand(1.8, 3);
    const x = l.x + Math.cos(a) * r;
    const y = l.y + Math.sin(a) * r * 0.7;
    stroke({
      path: [[x, y, 0.55 * (1 - reserve(x, y, l.r))]],
      brush: { type: 'soft', width: l.r * rand(2.5, 3.5) + 6 },
      color: 'lampWarm',
      paint: 'transparent',
      thinner: 0.75,
      load: 0.8,
    });
  }
}

// The flood sets before anything goes over it.
dry();

/**
 * Passage 2: the sky and the far end of the avenue, wet into wet.
 *
 * The rain sky darkens toward the top of the slot between the buildings, in soft
 * bands that run together. Far up the avenue the towers are only shapes in the rain:
 * pale violet-grey verticals, a stepped spire among them, laid with a soft brush and
 * then melted at their feet with a clean damp brush, so they rise out of the mist
 * instead of standing on it.
 */

const VP = { x: 630, y: 780 };
const EYE = 5;
const F = 1000;
const sx = (X, D) => VP.x + (X * F) / D;
const sy = (Z, D) => VP.y + ((EYE - Z) * F) / D;
const clamp01 = (v) => Math.min(1, Math.max(0, v));

palette('rainSky', mix(['payne', 1], ['ultra', 0.2], ['crimson', 0.15], ['water', 3]));
palette('haze', mix(['payne', 1], ['crimson', 0.35], ['water', 5]));
palette('hazeDeep', mix(['payne', 1], ['crimson', 0.3], ['ultra', 0.2], ['water', 2.6]));

/** The steam from the stack in the road (as in passage 1): its density at a point. */
const STACK = { x: sx(-3, 13), y: sy(2.4, 13) };
function steam(x, y) {
  const t = (STACK.y - y) / 420;
  if (t < -0.02 || t > 1.15) return 0;
  const u = Math.max(0, t);
  const cx = STACK.x - 150 * u ** 1.3 + 22 * noise(u * 3, 4.1);
  const half = 14 + 120 * u ** 0.8;
  const d = Math.abs(x - cx) / half;
  const n = 0.75 + 0.35 * noise(x / 40, y / 55);
  return clamp01((1 - d * d) * n * (1 - clamp01((t - 0.55) / 0.6)) * 1.25);
}

/** A path from (x0, y0) to (x1, y1), resampled every 6 px, lifting off through the steam. */
function spared(x0, y0, x1, y1, base) {
  const n = Math.max(2, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 6));
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = x0 + (x1 - x0) * t;
    const y = y0 + (y1 - y0) * t;
    pts.push([x, y, base * (1 - steam(x, y))]);
  }
  return pts;
}

brush('skyWash', { type: 'soft', width: 90, reservoir: 6 });
brush('tower', { type: 'soft', width: 26, reservoir: 3 });
brush('towerFine', { type: 'soft', width: 12, reservoir: 2 });
brush('damp', { type: 'soft', width: 40 });

/** The sky's three dishes, strong at the top of the slot to pale toward the glow. */
const DISH = { strong: 0.45, medium: 0.62, pale: 0.8 };

// The rain sky: level bands across the slot, heavy at the top and thinning to nothing
// toward the glow. Each band takes its wash from one of the three dishes, the changes
// between them wandering, and the walls will cover the sides, so the bands run past
// the slot.
for (let y = -20; y < 560; y += 24) {
  const t = clamp01(y / 560);
  const k = t + 0.14 * noise(y / 90, 3.3) + rand(-0.06, 0.06);
  if (rand() < t * 0.7) continue;
  const x0 = 380 + rand(-40, 40) + t * 60;
  const x1 = 1000 + rand(-40, 40) - t * 120;
  stroke({
    path: spared(x0, y + rand(-5, 5), x1, y + rand(-8, 8), 0.75 * (1 - t) + 0.2),
    brush: 'skyWash',
    color: 'rainSky',
    paint: 'transparent',
    thinner: k < 0.34 ? DISH.strong : k < 0.68 ? DISH.medium : DISH.pale,
    load: 0.85,
  });
}

/**
 * The far towers: x, top, and width in px. The tall one with the setbacks is the
 * spire; the rest are blocks of different heights fading into the glow.
 */
const TOWERS = [
  { x: 548, top: 610, w: 30 },
  { x: 580, top: 560, w: 34 },
  { x: 612, top: 640, w: 24 },
  { x: 700, top: 590, w: 36 },
  { x: 736, top: 650, w: 30 },
  { x: 760, top: 620, w: 26 },
];
for (const t of TOWERS) {
  for (let dx = -t.w / 2 + 6; dx <= t.w / 2 - 6; dx += 9) {
    const top = t.top + rand(-3, 3);
    stroke({
      path: spared(t.x + dx, top, t.x + dx + rand(-1, 1), VP.y + 6, 0.7),
      brush: 'tower',
      color: 'haze',
      paint: 'transparent',
      thinner: 0.5,
      load: 0.8,
    });
  }
}

// The spire: a stepped tower narrowing to a mast, in the deeper haze, with crisper
// edges than the rest since it is the one shape the eye should find.
const SPIRE = { x: 662, base: VP.y + 4 };
const STEPS = [
  { top: 470, w: 46 },
  { top: 400, w: 34 },
  { top: 350, w: 24 },
  { top: 318, w: 14 },
  { top: 296, w: 8 },
];
for (const s of STEPS) {
  for (let dx = -s.w / 2 + 3; dx <= s.w / 2 - 3; dx += 5) {
    stroke({
      path: spared(SPIRE.x + dx, s.top, SPIRE.x + dx, SPIRE.base, 0.75),
      brush: 'towerFine',
      color: 'hazeDeep',
      paint: 'transparent',
      thinner: 0.45,
      load: 0.85,
    });
  }
}
stroke({
  path: [
    [SPIRE.x, 300],
    [SPIRE.x, 236, 0.2],
  ],
  brush: { type: 'round', width: 4 },
  color: 'hazeDeep',
  paint: 'transparent',
  thinner: 0.3,
  load: 0.9,
  end: 'taper',
});

// A clean damp brush drawn level through the towers' feet and up their sides: the
// mist the avenue's far end dissolves into.
for (let y = VP.y - 10; y > 640; y -= 14) {
  stroke({
    path: [
      [500, y + rand(-4, 4)],
      [640, y + rand(-4, 4)],
      [800, y + rand(-4, 4)],
    ],
    brush: 'damp',
    pressure: 0.55,
  });
}
for (const t of [...TOWERS, { x: SPIRE.x - 22, top: 470 }, { x: SPIRE.x + 22, top: 470 }]) {
  stroke({
    path: [
      [t.x + rand(-8, 8), t.top + 10],
      [t.x + rand(-8, 8), VP.y],
    ],
    brush: 'damp',
    pressure: 0.45,
  });
}

dry();

/**
 * Passage 3: the walls of the avenue, painted around their lights.
 *
 * Each building is washed in strokes that run along its own perspective lines, the
 * courses of the wall, from the roofline down to the pavement: a cool grey high up,
 * and low down, while it is still wet, the warm tone the shop light throws up the
 * wall. The brush lifts off wherever a window or shopfront is lit, so those stay the
 * warm first wash: the lights are made by painting the dark around them, and because
 * the strokes run with the window rows, the saved shapes keep their perspective. The
 * wash comes from three dishes, strong for the near buildings, medium further up the
 * avenue, pale for the far ones, so the avenue recedes in steps. The far slivers by
 * the glow, too narrow to wash along, take upright strokes. When the walls are dry,
 * the windows go in, each a few narrow strokes along its row, and then the cornices.
 */

const W = canvas.width;
const H = canvas.height;
const VP = { x: 630, y: 780 };
const EYE = 5;
const F = 1000;
const sx = (X, D) => VP.x + (X * F) / D;
const sy = (Z, D) => VP.y + ((EYE - Z) * F) / D;
const clamp01 = (v) => Math.min(1, Math.max(0, v));
const hash = (a, b, c) => {
  const s = Math.sin(a * 127.1 + b * 311.7 + c * 74.7) * 43758.5453;
  return s - Math.floor(s);
};

// The wall piles: a warm brownstone, a cool limestone, a blue slate, a dark tower, and
// the warm low tone the shop light throws up the walls.
palette('brick', mix(['sienna', 0.7], ['crimson', 0.4], ['payne', 1], ['water', 1.6]));
palette('stone', mix(['payne', 1], ['crimson', 0.3], ['ochre', 0.25], ['water', 2.2]));
palette('slate', mix(['payne', 1.2], ['ultra', 0.3], ['crimson', 0.15], ['water', 1.6]));
palette('towerDark', mix(['payne', 1.4], ['crimson', 0.45], ['ultra', 0.25], ['water', 0.3]));
palette('wallLow', mix(['ochre', 1], ['crimson', 0.3], ['payne', 0.3], ['water', 2.5]));
palette('windowDark', mix(['payne', 1.4], ['crimson', 0.4], ['ultra', 0.3]));
palette('windowGold', mix(['gamboge', 1], ['ochre', 0.8], ['scarlet', 0.1], ['water', 3.5]));
palette('shopGold', mix(['gamboge', 1.6], ['ochre', 0.6], ['scarlet', 0.3], ['water', 3]));

/** The three dishes of wash: how much water each one carries. */
const DISH = { strong: 0.36, medium: 0.55, pale: 0.72 };
/** The dish a building at distance D takes; the boundaries are where a hand would put them, not a ruler. */
function dishAt(D) {
  const d = D + rand(-6, 6);
  if (d < 30) return 'strong';
  if (d < 90) return 'medium';
  return 'pale';
}
/** One dish paler: the shop light's warmth goes on wetter than the wall above it. */
const paler = (dish) => (dish === 'strong' ? 'medium' : 'pale');

/** The buildings along each wall: distance range (m), height (m), and pile. */
const WALLS = [
  {
    X: -7.5,
    blocks: [
      { d0: 3, d1: 22, h: 80, pile: 'towerDark' },
      { d0: 22, d1: 35, h: 34, pile: 'brick' },
      { d0: 35, d1: 52, h: 46, pile: 'stone' },
      { d0: 52, d1: 75, h: 28, pile: 'brick' },
      { d0: 75, d1: 110, h: 52, pile: 'slate' },
      { d0: 110, d1: 160, h: 36, pile: 'stone' },
      { d0: 160, d1: 260, h: 60, pile: 'slate' },
    ],
  },
  {
    X: 7.75,
    blocks: [
      { d0: 3, d1: 25, h: 90, pile: 'stone' },
      { d0: 25, d1: 40, h: 30, pile: 'brick' },
      { d0: 40, d1: 58, h: 55, pile: 'slate' },
      { d0: 58, d1: 85, h: 24, pile: 'brick' },
      { d0: 85, d1: 130, h: 44, pile: 'stone' },
      { d0: 130, d1: 240, h: 70, pile: 'slate' },
    ],
  },
];

/**
 * Whether a point of a wall (distance D, height Z, in building b) is a lit window: bays
 * every 3.2 m, a shopfront along the ground floor (most of them lit), and upper
 * windows every 3.3 m, a few of them lit. 2 is a lit shopfront, 1 a lit window, -1 an
 * unlit window, 0 wall.
 */
function windowAt(D, Z, b, wi) {
  if (D < b.d0 || D >= b.d1 || Z < 0 || Z > b.h) return 0;
  const bay = Math.floor((D - b.d0) / 3.2);
  const u = D - b.d0 - bay * 3.2;
  if (Z < 4) {
    if (u < 0.5 || u > 2.7 || Z < 0.8 || Z > 3.1) return 0;
    return hash(bay, wi, b.d0) < 0.65 ? 2 : 0;
  }
  if (Z > b.h - 2) return 0;
  const floor = Math.floor((Z - 4.6) / 3.3);
  const v = Z - 4.6 - floor * 3.3;
  if (u < 0.8 || u > 2.2 || v < 0.6 || v > 2.6) return 0;
  return hash(bay * 7 + floor, wi, b.d0 + 1) < 0.22 ? 1 : -1;
}

/** Steam from the stack in the road (as in passage 1). */
const STACK = { x: sx(-3, 13), y: sy(2.4, 13) };
function steam(x, y) {
  const t = (STACK.y - y) / 420;
  if (t < -0.02 || t > 1.15) return 0;
  const u = Math.max(0, t);
  const cx = STACK.x - 150 * u ** 1.3 + 22 * noise(u * 3, 4.1);
  const half = 14 + 120 * u ** 0.8;
  const d = Math.abs(x - cx) / half;
  const n = 0.75 + 0.35 * noise(x / 40, y / 55);
  return clamp01((1 - d * d) * n * (1 - clamp01((t - 0.55) / 0.6)) * 1.25);
}

/** The lamp heads (as in passage 1), kept bright. */
const LAMPS = [
  { X: -3.6, D: 8 },
  { X: 3.5, D: 15 },
  { X: -3.6, D: 38 },
  { X: 3.5, D: 46 },
  { X: -3.6, D: 70 },
  { X: 3.5, D: 85 },
  { X: -3.6, D: 120 },
  { X: 3.5, D: 150 },
].map((l) => ({ x: sx(l.X, l.D), y: sy(7.5, l.D), r: (0.35 * F) / l.D }));

/**
 * How strongly the wall brush lifts at wall point (D, Z): a lit window or shopfront
 * within about a third of a brush of the brush's middle, a lamp head, the steam.
 */
function reserve(w, wi, b, D, Z, bw) {
  const x = sx(w.X, D);
  const y = sy(Z, D);
  let s = steam(x, y);
  for (const l of LAMPS)
    s = Math.max(s, clamp01(1 - (Math.hypot(x - l.x, y - l.y) - l.r) / (bw * 0.5)));
  // a third of a brush, in metres along the wall and up it: the wash creeps a little
  // into the gap, which leaves the window's edge soft
  const dD = (0.32 * bw * D * D) / (Math.abs(w.X) * F);
  const dZ = (0.32 * bw * D) / F;
  for (const [a, c] of [
    [0, 0],
    [-dD, 0],
    [dD, 0],
    [0, -dZ],
    [0, dZ],
  ]) {
    if (windowAt(D + a, Z + c, b, wi) > 0) return 1;
  }
  return s;
}

/** The distance at which a wall reaches screen x. */
const dAtX = (w, x) => (w.X * F) / (x - VP.x);

// The washes, building by building, far ones first so the near walls overlap them.
for (let wi = 0; wi < 2; wi++) {
  const w = WALLS[wi];
  for (const b of [...w.blocks].reverse()) {
    // the part of the building on the canvas
    const dn = Math.max(b.d0, dAtX(w, wi === 0 ? -60 : W + 60));
    if (dn >= b.d1) continue;
    const df = b.d1;
    const mid = (dn + df) / 2;
    const dish = dishAt(mid);
    const xSpan = Math.abs(sx(w.X, df) - sx(w.X, dn));
    const zWarm = 5.5 + rand(-1, 1.5);
    if (xSpan > 100) {
      // along the courses: one stroke per row of the wall, top down, the brush lifting
      // over the lit windows it crosses
      const bw = Math.min(46, Math.max(8, (0.75 * F) / mid));
      const dZ = (0.3 * bw * mid) / F;
      const zTop = Math.min(b.h, EYE + ((VP.y + 50) * df) / F);
      for (let Z = zTop - dZ * 0.3; Z > -dZ; Z -= dZ * rand(0.9, 1.1)) {
        // the warm foot knits into the cool wall over a metre or so
        const warm = Z < zWarm + rand(-0.8, 0.8);
        const path = [];
        // a little past each end, so the courses run into the neighbors
        const ext = (0.4 * bw * dn * dn) / (Math.abs(w.X) * F);
        const d0 = Math.max(1.5, dn - ext);
        const d1 = df + (0.4 * bw * df * df) / (Math.abs(w.X) * F);
        const n = Math.max(2, Math.ceil(xSpan / 5));
        for (let i = 0; i <= n; i++) {
          // even steps in screen x, not in distance
          const x = sx(w.X, d0) + ((sx(w.X, d1) - sx(w.X, d0)) * i) / n;
          const D = dAtX(w, x);
          const y = sy(Z, D);
          if (y < -200) continue;
          path.push([x, y, 0.75 * (1 - reserve(w, wi, b, D, Z, bw))]);
        }
        if (path.length < 2) continue;
        stroke({
          path,
          brush: { type: 'soft', width: bw, reservoir: 6 },
          color: warm ? 'wallLow' : b.pile,
          paint: 'transparent',
          thinner: DISH[warm ? paler(dish) : dish],
          load: 0.9,
        });
      }
    } else {
      // a far sliver: upright strokes from the roofline to the pavement
      const bw = Math.min(14, Math.max(5, (1.3 * F) / mid));
      const [xa, xb] = [sx(w.X, df), sx(w.X, dn)].sort((p, q) => p - q);
      for (let x = xa + bw * 0.3; x <= xb - bw * 0.2; x += bw * rand(0.32, 0.42)) {
        const D = dAtX(w, x);
        for (const [za, zb, pile, d] of [
          [b.h, 0, b.pile, dish],
          [zWarm, 0, 'wallLow', paler(dish)],
        ]) {
          const ya = Math.max(-40, sy(za, D));
          const yb = sy(zb, D) + 2;
          const n = Math.ceil((yb - ya) / 5);
          const path = [];
          for (let i = 0; i <= n; i++) {
            const y = ya + ((yb - ya) * i) / n;
            const Z = EYE - ((y - VP.y) * D) / F;
            path.push([x, y, 0.75 * (1 - reserve(w, wi, b, D, Z, bw))]);
          }
          stroke({
            path,
            brush: { type: 'soft', width: bw, reservoir: 5 },
            color: pile,
            paint: 'transparent',
            thinner: DISH[d],
            load: 0.9,
          });
        }
      }
    }
  }
}

// The walls set before their windows and edges are drawn over them.
dry();

/**
 * Fill one window of wall w, from distance Da to Db and height z0 to z1, in a single
 * stroke that zigzags up and down across it, as a hand fills a small shape: the edge
 * of the fill is the path's edge, so the window keeps its perspective, slanted top and
 * upright sides, with no stroke ends showing.
 */
function pane(w, Da, Db, z0, z1, color, dish) {
  const Dm = (Da + Db) / 2;
  const hpx = ((z1 - z0) * F) / Dm;
  const wpx = Math.abs(sx(w.X, Db) - sx(w.X, Da));
  const bw = Math.max(1.5, Math.min(14, Math.min(wpx, hpx) * 0.45));
  // half a brush in from each side, in metres along the wall and up it
  const inD = (D) => (0.5 * bw * D * D) / (Math.abs(w.X) * F);
  const inZ = (D) => (0.5 * bw * D) / F;
  const a = Da + inD(Da);
  const b = Db - inD(Db);
  const path = [];
  if (b <= a || wpx < bw * 1.3) {
    path.push([sx(w.X, Dm), sy(z1 - inZ(Dm), Dm)], [sx(w.X, Dm), sy(z0 + inZ(Dm), Dm)]);
  } else {
    const m = Math.max(1, Math.ceil(wpx / (bw * 0.55)));
    for (let k = 0; k <= m; k++) {
      const D = a + ((b - a) * k) / m;
      const top = [sx(w.X, D), sy(z1 - inZ(D), D)];
      const bottom = [sx(w.X, D), sy(z0 + inZ(D), D)];
      if (k % 2) path.push(bottom, top);
      else path.push(top, bottom);
    }
  }
  stroke({
    path,
    brush: { type: 'round', width: bw, streak: 0, reservoir: 6 },
    color,
    paint: 'transparent',
    thinner: DISH[dish],
    load: 0.9,
    pressure: 0.85,
    corners: true,
    end: 'stop',
  });
}

// Lit windows take a warm stain; shopfronts a hotter one. Unlit windows are dark,
// though most are left to the wash. Bay by bay, floor by floor, as a hand would go.
for (let wi = 0; wi < 2; wi++) {
  const w = WALLS[wi];
  for (const b of w.blocks) {
    for (let bay = 0; b.d0 + bay * 3.2 < b.d1 - 1; bay++) {
      const D0 = b.d0 + bay * 3.2;
      const onCanvas = (D) => sx(w.X, D) > -20 && sx(w.X, D) < W + 20;
      // the near windows are the darkest; up the avenue the rain air pales them
      const dish = D0 < 26 + rand(-4, 4) ? 'strong' : D0 < 70 + rand(-8, 8) ? 'medium' : 'pale';
      if (onCanvas(D0 + 0.55) && hash(bay, wi, b.d0) < 0.65)
        pane(w, D0 + 0.55, Math.min(b.d1, D0 + 2.65), 0.9, 3.0, 'shopGold', 'medium');
      for (let floor = 0; 4.6 + floor * 3.3 + 2.6 < b.h - 2; floor++) {
        const lit = hash(bay * 7 + floor, wi, b.d0 + 1) < 0.22;
        // most unlit windows are left to the wash, and up the avenue all of them are
        if (!lit && (D0 > 90 || hash(floor * 3 + bay, wi + 5, b.d0) < (D0 < 30 ? 0.45 : 0.65)))
          continue;
        const Da = D0 + 0.8;
        const Db = D0 + 2.2;
        if (Db > b.d1 || !onCanvas(Da)) continue;
        const z0 = 4.6 + floor * 3.3 + 0.6;
        const Dm = (Da + Db) / 2;
        if (sy(z0, Dm) < -40 || sy(z0 + 2, Dm) > H) continue;
        // a lit pane spreads a little over the paper saved round it, to soften its rim
        const g = lit ? 0.12 : 0;
        pane(
          w,
          Da - g,
          Db + g,
          z0 - g,
          z0 + 2 + g,
          lit ? 'windowGold' : 'windowDark',
          lit ? 'medium' : dish,
        );
      }
    }
  }
}

// Cornices and the edges between buildings: a dark line along each roofline, and the
// upright where one building stands in front of the next.
for (let wi = 0; wi < 2; wi++) {
  const w = WALLS[wi];
  for (const b of w.blocks) {
    const pts = [];
    for (let k = 0; k <= 8; k++) {
      const D = b.d0 + ((b.d1 - b.d0) * k) / 8;
      const p = [sx(w.X, D), sy(b.h, D)];
      if (p[1] > -150 && p[0] > -150 && p[0] < W + 150) pts.push(p);
    }
    const f = F / ((b.d0 + b.d1) / 2);
    if (pts.length > 1)
      stroke({
        path: pts,
        brush: { type: 'round', width: Math.max(2, 0.5 * f) },
        color: 'windowDark',
        paint: 'glaze',
        thinner: 0.4,
        load: 0.85,
      });
    const xe = sx(w.X, b.d1);
    if (xe > 0 && xe < W && b.d1 < 200)
      stroke({
        path: [
          [xe, Math.max(-10, sy(b.h, b.d1))],
          [xe, sy(0, b.d1)],
        ],
        brush: { type: 'round', width: Math.max(1.5, 0.3 * (F / b.d1)) },
        color: 'windowDark',
        paint: 'glaze',
        thinner: 0.5,
        load: 0.8,
      });
  }
}

dry();

/**
 * Passage 4: the wet road, which is a mirror.
 *
 * Every point of the road and pavement reflects the wall or sky above it, flipped
 * about the foot of the wall it faces. So this passage looks at the painting it has
 * so far: at() reads the dried color at the mirrored point, and a short upright
 * stroke carries that color, dulled with the road's grey, down onto the wet surface.
 * The lit shopfronts, the lamps, and the glow at the far end come down as long warm
 * streaks; the dark walls as dark ones. Laid wet together, they run into each other,
 * and a clean damp brush drawn downward through them pulls them into the long smears
 * of a rainy street. The paper saved under the headlights and lamps stays bare.
 */

const W = canvas.width;
const H = canvas.height;
const VP = { x: 630, y: 780 };
const EYE = 5;
const F = 1000;
const sx = (X, D) => VP.x + (X * F) / D;
const sy = (Z, D) => VP.y + ((EYE - Z) * F) / D;
const clamp01 = (v) => Math.min(1, Math.max(0, v));

palette('roadGrey', mix(['payne', 1], ['crimson', 0.3], ['water', 2.5]));
palette('pavement', mix(['payne', 1], ['ochre', 0.3], ['crimson', 0.2], ['water', 3]));
palette('curb', mix(['payne', 1.3], ['crimson', 0.4], ['ultra', 0.2]));

const WALL_X = { left: -7.5, right: 7.75 };
const CURB_X = { left: -4.75, right: 4.6 };

/** The road point at screen (x, y): distance D and offset X, or null above the horizon. */
function groundAt(x, y) {
  if (y <= VP.y + 1) return null;
  const D = (EYE * F) / (y - VP.y);
  const X = ((x - VP.x) * D) / F;
  if (X < WALL_X.left || X > WALL_X.right) return null;
  return { D, X };
}

/**
 * Where the reflection at screen (x, y) comes from: the reflected ray meets the wall
 * on that side at distance Dw, and the image there is the wall flipped about its foot.
 */
function mirrorY(x, y) {
  const dx = x - VP.x;
  const Xw = dx < 0 ? WALL_X.left : WALL_X.right;
  const Dw = Math.abs(dx) < 1 ? 1e4 : Math.min(1e4, (Xw * F) / dx);
  const foot = sy(0, Dw);
  return Math.max(2, 2 * foot - y);
}

/** Lamps and headlights (as in passage 1): their reflections stay bare paper. */
const LAMPS = [
  { X: -3.6, D: 8 },
  { X: 3.5, D: 15 },
  { X: -3.6, D: 38 },
  { X: 3.5, D: 46 },
  { X: -3.6, D: 70 },
  { X: 3.5, D: 85 },
  { X: -3.6, D: 120 },
  { X: 3.5, D: 150 },
].map((l) => ({ x: sx(l.X, l.D), y: sy(7.5, l.D), r: (0.35 * F) / l.D, gy: sy(0, l.D) }));
const HEADLIGHTS = [
  { X: -3.1, D: 24 },
  { X: -1.7, D: 24 },
  { X: -3.6, D: 60 },
  { X: -1.6, D: 60 },
  { X: -2.9, D: 110 },
  { X: -1.8, D: 110 },
  { X: -3.2, D: 190 },
  { X: -2.2, D: 190 },
].map((h) => ({
  x: sx(h.X, h.D),
  y: sy(0.65, h.D),
  r: Math.max(2, (0.22 * F) / h.D),
  gy: sy(0, h.D),
}));

/** Steam from the stack in the road (as in passage 1). */
const STACK = { x: sx(-3, 13), y: sy(2.4, 13) };
function steam(x, y) {
  const t = (STACK.y - y) / 420;
  if (t < -0.02 || t > 1.15) return 0;
  const u = Math.max(0, t);
  const cx = STACK.x - 150 * u ** 1.3 + 22 * noise(u * 3, 4.1);
  const half = 14 + 120 * u ** 0.8;
  const d = Math.abs(x - cx) / half;
  const n = 0.75 + 0.35 * noise(x / 40, y / 55);
  return clamp01((1 - d * d) * n * (1 - clamp01((t - 0.55) / 0.6)) * 1.25);
}

/** The crosswalk (as in passage 1): its stripes take the reflections only lightly. */
function crosswalk(x, y) {
  const g = groundAt(x, y);
  if (!g || g.D < 7 || g.D > 8.6 || g.X < -4.5 || g.X > 4.4) return 0;
  return (g.X + 10) % 1.1 < 0.6 ? 1 : 0;
}

/** How strongly the brush lifts at a point. */
function reserve(x, y, m) {
  let s = Math.max(steam(x, y), 0.5 * crosswalk(x, y));
  for (const l of LAMPS) {
    if (y < l.gy) continue;
    const len = (l.gy - l.y) * 1.3;
    const d =
      Math.hypot((x - l.x) * 2.2, Math.max(0, Math.abs(y - l.gy - len / 2) - len / 2) * 0.5) - l.r;
    s = Math.max(s, 0.8 * clamp01(1 - d / m));
  }
  for (const h of HEADLIGHTS) {
    if (y < h.gy - h.r) continue;
    const len = (h.gy - h.y) * 6;
    const d = Math.hypot((x - h.x) * 2.5, Math.max(0, y - h.gy - len) * 0.4) - h.r * 0.8;
    s = Math.max(s, 0.9 * clamp01(1 - d / m));
  }
  return s;
}

/** Three dishes for the road: the near road takes the strongest wash, the far end the palest. */
const DISH = { strong: 0.25, medium: 0.35, pale: 0.45 };
/** The dish at a point of the road, its edges ragged where the wash ran. */
function dishAt(x, y, near) {
  const k = near + 0.1 * noise(x / 110, y / 70) + rand(-0.04, 0.04);
  return k > 0.55 ? DISH.strong : k > 0.2 ? DISH.medium : DISH.pale;
}

// The reflections: rows from the far end toward us, each a run of short upright
// strokes, longer and wider as the road comes closer. Each carries the mirrored color,
// darkened with the road's grey; the pavements beyond the curbs reflect less.
for (let y = VP.y + 3; y < H + 10; y += 3 + (y - VP.y) * 0.035) {
  const near = (y - VP.y) / (H - VP.y);
  const step = 4 + near * 14;
  for (let x = rand(-8, 0); x < W + 8; x += step * rand(0.8, 1.2)) {
    const g = groundAt(x, y);
    if (!g) continue;
    const pave = g.X < CURB_X.left || g.X > CURB_X.right;
    const seen = at(x, mirrorY(x, y));
    const len = 14 + near * 120 + rand(0, 20 + near * 60);
    const m = step * 0.9;
    stroke({
      path: [
        [x, y, 0.7 * (1 - reserve(x, y, m))],
        [x + rand(-1, 1), y + len / 2, 0.75 * (1 - reserve(x, y + len / 2, m))],
        [x + rand(-1, 1), y + len, 0.6 * (1 - reserve(x, y + len, m))],
      ],
      brush: { type: 'soft', width: step * 2.6 },
      color: mix([seen, pave ? 1.4 : 2.4], [pave ? 'pavement' : 'roadGrey', 1]),
      paint: 'transparent',
      thinner: dishAt(x, y, near),
      load: 0.85,
    });
  }
}

// A clean damp brush drawn straight down through the wet reflections, again and
// again: the streaks of a rain-soaked road.
for (let k = 0; k < 420; k++) {
  const x = rand(-10, W + 10);
  const y = rand(VP.y + 10, H - 40);
  const near = (y - VP.y) / (H - VP.y);
  const len = 40 + near * rand(80, 260);
  stroke({
    path: [
      [x, y],
      [x + rand(-2, 2), y + len],
    ],
    brush: { type: 'soft', width: 10 + near * 30 },
    pressure: rand(0.5, 0.75),
    end: 'taper',
  });
}

// The curbs: a dark line each side, running up to the far end, finer as it goes.
for (const X of [CURB_X.left, CURB_X.right]) {
  for (const [D0, D1] of [
    [5, 9],
    [9, 16],
    [16, 30],
    [30, 60],
    [60, 140],
  ]) {
    stroke({
      path: [
        [sx(X, D0), sy(0, D0)],
        [sx(X, D1), sy(0, D1)],
      ],
      brush: { type: 'round', width: Math.max(1.2, (0.16 * F) / ((D0 + D1) / 2)) },
      color: 'curb',
      paint: 'glaze',
      thinner: 0.3,
      load: 0.8,
    });
  }
}

dry();

/**
 * Passage 5: the life of the street, the crisp edges of the picture.
 *
 * Over the dried road go the things that move through it: two yellow cabs, a dark
 * car and a bus far up the avenue, the orange-and-white steam stack, the lamp posts
 * and the traffic signal, and people under umbrellas, one of them red, crossing at
 * the crosswalk. These carry the hardest edges in the painting, laid with round and
 * flat brushes in strong paint, each small form blocked in with one stroke swept back
 * and forth across it. Each one also drops its reflection into the wet road below it:
 * a soft smear of its own colors, dragged down with a damp brush.
 */

const VP = { x: 630, y: 780 };
const EYE = 5;
const F = 1000;
const sx = (X, D) => VP.x + (X * F) / D;
const sy = (Z, D) => VP.y + ((EYE - Z) * F) / D;
const clamp01 = (v) => Math.min(1, Math.max(0, v));

palette('cabYellow', mix(['gamboge', 2], ['ochre', 0.6], ['scarlet', 0.08]));
palette('cabShade', mix(['gamboge', 1], ['ochre', 1], ['sienna', 0.4], ['payne', 0.2]));
palette('ink', mix(['payne', 1.4], ['crimson', 0.45], ['ultra', 0.3]));
palette('coat', mix(['payne', 1.2], ['sienna', 0.3], ['crimson', 0.35]));
palette('umbrellaRed', mix(['scarlet', 1.5], ['crimson', 0.7]));
palette('tail', mix(['scarlet', 2], ['crimson', 0.3]));
palette('signalRed', mix(['scarlet', 2], ['gamboge', 0.15]));
palette('stackOrange', mix(['scarlet', 1], ['gamboge', 1.2]));
palette('stackShade', mix(['payne', 1], ['crimson', 0.3], ['water', 3]));
palette('glowWarm', mix(['gamboge', 2], ['scarlet', 0.3], ['water', 3]));

/** Steam from the stack (as in passage 1): what it hides is painted faintly. */
const STACK = { X: -3, D: 13, x: sx(-3, 13), y: sy(2.4, 13) };
function steam(x, y) {
  const t = (STACK.y - y) / 420;
  if (t < -0.02 || t > 1.15) return 0;
  const u = Math.max(0, t);
  const cx = STACK.x - 150 * u ** 1.3 + 22 * noise(u * 3, 4.1);
  const half = 14 + 120 * u ** 0.8;
  const d = Math.abs(x - cx) / half;
  const n = 0.75 + 0.35 * noise(x / 40, y / 55);
  return clamp01((1 - d * d) * n * (1 - clamp01((t - 0.55) / 0.6)) * 1.25);
}

/** Pressure at a point, eased off where the steam veils it. */
const veil = (x, y, p) => p * (1 - 0.85 * steam(x, y));

/**
 * A level band of flat color from x0 to x1, centered on yc, h px tall, in as many
 * rows as it takes; `gaps` are x positions where the brush lifts (a saved light).
 */
function band(x0, x1, yc, h, color, gaps = [], gapHalf = 0) {
  const rows = Math.max(1, Math.ceil(h / 34));
  const rh = h / rows;
  for (let r = 0; r < rows; r++) {
    const y = yc - h / 2 + rh * (r + 0.5);
    const n = Math.max(2, Math.ceil((x1 - x0) / 3));
    const path = [];
    for (let i = 0; i <= n; i++) {
      const x = x0 + ((x1 - x0) * i) / n;
      const lift = gaps.some((g) => Math.abs(x - g) < gapHalf) ? 0 : 1;
      path.push([x, y, veil(x, y, 0.85) * lift]);
    }
    stroke({
      path,
      brush: { type: 'flat', width: rh * 1.08, streak: 0.1 },
      color,
      paint: 'transparent',
      load: 0.95,
      end: 'stop',
    });
  }
}

/** A reflection: a soft upright smear of a color under a point of the road. */
function reflect(x, y, len, width, color, thinner = 0.3) {
  stroke({
    path: [
      [x, y, veil(x, y, 0.75)],
      [x + rand(-1, 1), y + len * 0.5, 0.6],
      [x + rand(-1, 1), y + len, 0.25],
    ],
    brush: { type: 'soft', width },
    color,
    paint: 'transparent',
    thinner,
    load: 0.85,
    end: 'taper',
  });
}
/** A clean damp brush pulled down through wet paint. */
function drag(x, y, len, width) {
  stroke({
    path: [
      [x, y],
      [x + rand(-1.5, 1.5), y + len],
    ],
    brush: { type: 'soft', width },
    pressure: 0.55,
    end: 'taper',
  });
}

/**
 * One confident stroke of strong paint, level across from x0 to x1 at height y: a
 * round brush, so its ends come out rounded the way a loaded brush leaves them.
 */
function slab(x0, x1, y, h, color, p = 0.85, thinner = 0) {
  stroke({
    path: [
      [x0 + h * 0.3, y + rand(-0.5, 0.5), veil(x0, y, p)],
      [(x0 + x1) / 2, y + rand(-0.8, 0.8), veil((x0 + x1) / 2, y, p)],
      [x1 - h * 0.3, y + rand(-0.5, 0.5), veil(x1, y, p)],
    ],
    brush: { type: 'round', width: h, streak: 0.15 },
    color,
    paint: 'transparent',
    thinner,
    load: 0.95,
    end: 'stop',
  });
}

/**
 * Fill a shape in one stroke that sweeps back and forth across it, top to bottom, the
 * way a loaded brush blocks in a small form: `span(y)` gives the shape's left and right
 * edge at height y, and the fill's edge is the path's edge, so the silhouette is clean.
 * `p(t)` is the pressure from top (0) to bottom (1).
 */
function fill(span, y0, y1, bw, color, p = () => 0.85, thinner = 0) {
  const path = [];
  const rows = Math.max(1, Math.ceil((y1 - y0 - bw) / (bw * 0.5)));
  for (let r = 0; r <= rows; r++) {
    const y = y0 + bw / 2 + ((y1 - y0 - bw) * r) / rows;
    const [a, b] = span(y);
    const t = (y - y0) / (y1 - y0);
    const ends = [
      [a + bw / 2, y, veil(a, y, p(t))],
      [Math.max(a + bw / 2, b - bw / 2), y, veil(b, y, p(t))],
    ];
    if (r % 2) ends.reverse();
    path.push(...ends);
  }
  stroke({
    path,
    brush: { type: 'round', width: bw, streak: 0, splay: 0, reservoir: 6 },
    color,
    paint: 'transparent',
    thinner,
    load: 0.95,
    corners: true,
    end: 'stop',
  });
}

/**
 * A car seen from a little above, in the few strokes a painter gives a car in the
 * rain: cabin and body blocked in as one mass of color with a clean silhouette and its
 * foot lost into its own reflection, the dark glass dropped into the cabin, then the
 * lights and the dark under it. A car coming toward us keeps the paper saved for its
 * headlights in passage 1; one going away shows red taillights.
 */
function car({ X, D, w, len, body, coming, cab }) {
  const f = F / D;
  const X0 = X - w / 2;
  const X1 = X + w / 2;
  const xl = sx(X0, D);
  const xr = sx(X1, D);
  const xm = (xl + xr) / 2;
  const roofNear = D + 0.9;
  const roofFar = D + len * 0.6;
  const rl = sx(X0 + 0.25, roofNear);
  // the whole car first as one yellow mass, cabin and body together: the cabin a
  // little narrower, its corners rounded, the body's foot laid lighter so it is lost in
  // the wet
  const top = sy(1.0, D);
  const bottom = sy(0.3, D);
  const roofY = sy(1.45, roofFar);
  const bwFill = Math.max(2, Math.min(9, (bottom - roofY) / 6));
  fill(
    (y) => {
      if (y >= top) return [xl, xr];
      const t = clamp01((y - roofY) / (top - roofY));
      const inset = (rl - xl) * (1 - t) ** 0.6;
      return [xl + inset, xr - inset];
    },
    roofY,
    bottom,
    bwFill,
    body,
    (t) => (t < 0.8 ? 0.85 : 0.55),
  );
  // the glass: dark, in the cabin, with the yellow left showing round it
  const gTop = sy(1.4, roofNear);
  const gBot = sy(1.03, D + 0.2);
  if (gBot - gTop > 3)
    fill(
      (y) => {
        const t = clamp01((y - gTop) / (gBot - gTop));
        const inset = (rl - xl) * (1 - t) * 0.8 + f * 0.12;
        return [xl + inset, xr - inset];
      },
      gTop,
      gBot,
      Math.max(1.5, Math.min(6, (gBot - gTop) / 3)),
      'ink',
      () => 0.85,
    );
  // the dark under the car and the two tyres, all one dark, lost at the bottom
  const lampY = sy(0.65, D);
  const lamps = [sx(X0 + 0.3, D), sx(X1 - 0.3, D)];
  slab(xl + f * 0.05, xr - f * 0.05, sy(0.2, D), f * 0.2, 'ink', 0.8);
  for (const x of [xl + f * 0.22, xr - f * 0.22])
    stroke({
      path: [
        [x, sy(0.35, D), 0.8],
        [x + rand(-1, 1), sy(0, D) + f * 0.04, 0.5],
      ],
      brush: { type: 'round', width: f * 0.24 },
      color: 'ink',
      paint: 'transparent',
      load: 0.95,
      end: 'taper',
    });
  if (coming) {
    // the paper saved for the headlights gets a crisp dark ring of bumper round it
    slab(xl + f * 0.1, xr - f * 0.1, lampY + f * 0.16, f * 0.08, 'ink', 0.7, 0.3);
  }
  if (cab) {
    // the lit sign on the roof: a small hot stroke with a hard edge, where the eye lands
    const sD = D + len * 0.35;
    const sxm = sx(X, sD);
    slab(sxm - f * 0.24, sxm + f * 0.24, sy(1.68, sD), f * 0.14, 'glowWarm', 0.9);
  }
  if (!coming) {
    for (const lx of lamps) {
      stroke({
        path: [[lx, sy(0.78, D), 0.9]],
        brush: { type: 'soft', width: f * 0.85 },
        color: 'tail',
        paint: 'transparent',
        thinner: 0.75,
        load: 0.8,
      });
      stroke({
        path: [[lx, sy(0.78, D), 0.9]],
        brush: { type: 'round', width: Math.max(3, f * 0.22) },
        color: 'tail',
        paint: 'transparent',
        load: 1,
      });
    }
  }
  // its reflection: the body color and its lights smeared down the road toward us
  const gy = sy(0, D);
  for (let k = 0; k < 5; k++)
    reflect(
      xl + (xr - xl) * (0.1 + 0.8 * rand()),
      gy + 2,
      f * rand(0.9, 1.9),
      Math.max(4, (xr - xl) * 0.2),
      body,
      0.45,
    );
  if (!coming)
    for (const lx of lamps) reflect(lx, gy + 2, f * 2.4, Math.max(3, f * 0.24), 'tail', 0.2);
  drag(xm, gy - f * 0.1, f * 2.2, (xr - xl) * 0.7);
}

// The far traffic first: taillights as dabs up the avenue, each with its streak.
for (const [X, D] of [
  [1.4, 80],
  [2.6, 80],
  [1.6, 130],
  [2.7, 130],
  [1.5, 210],
  [2.5, 210],
]) {
  const x = sx(X, D);
  stroke({
    path: [[x, sy(0.8, D)]],
    brush: { type: 'soft', width: Math.max(3, (0.5 * F) / D) },
    color: 'tail',
    paint: 'transparent',
    load: 1,
  });
  reflect(x, sy(0, D), (2 * F) / D, Math.max(2, (0.3 * F) / D), 'tail', 0.3);
}

// The bus coming down the far avenue: dark face, its lit destination sign, and the
// headlights the paper keeps.
{
  const D = 60;
  const xl = sx(-3.9, D);
  const xr = sx(-1.3, D);
  band(xl, xr, (sy(3.1, D) + sy(1.6, D)) / 2, sy(1.6, D) - sy(3.1, D), 'ink');
  band(xl + 2, xr - 2, sy(2.85, D), 4, 'glowWarm');
  band(
    xl,
    xr,
    (sy(1.6, D) + sy(0.3, D)) / 2,
    sy(0.3, D) - sy(1.6, D),
    'coat',
    [sx(-3.6, D), sx(-1.6, D)],
    3,
  );
  reflect((xl + xr) / 2, sy(0, D), 60, (xr - xl) * 0.6, 'coat', 0.4);
}

car({ X: 1.9, D: 35, w: 1.9, len: 4.5, body: 'coat' });
car({ X: -2.4, D: 24, w: 1.9, len: 4.6, body: 'cabYellow', coming: true, cab: true });
car({ X: 2.2, D: 13.5, w: 1.9, len: 4.6, body: 'cabYellow', cab: true });

// The steam stack: a tube banded orange and white (the white is the paper), shaded on
// the side away from the light.
{
  const f = F / STACK.D;
  const x = STACK.x;
  const half = 0.2 * f;
  stroke({
    path: [
      [x + half * 0.55, sy(0, STACK.D)],
      [x + half * 0.55, sy(2.4, STACK.D)],
    ],
    brush: { type: 'soft', width: half * 0.9 },
    color: 'stackShade',
    paint: 'transparent',
    load: 0.9,
  });
  for (let z = 0.05; z < 2.35; z += 0.42) {
    band(x - half, x + half, sy(z + 0.1, STACK.D), 0.2 * f, 'stackOrange');
  }
  band(x - half * 1.1, x + half * 1.1, sy(2.38, STACK.D), 0.08 * f, 'ink');
  reflect(x, sy(0, STACK.D), 120, half * 1.6, 'stackOrange', 0.3);
}

/** A lamp post: pole up from the curb, an arm out over the road, the dark head. */
function lamp(Xc, D, side) {
  const f = F / D;
  const w = Math.max(1.5, f * 0.16);
  const x = sx(Xc, D);
  const head = sx(Xc - side * 1.6, D);
  stroke({
    path: [
      [x, sy(0, D), veil(x, sy(0, D), 0.85)],
      [x, sy(4, D), veil(x, sy(4, D), 0.8)],
      [x, sy(7.6, D), 0.7],
    ],
    brush: { type: 'round', width: w },
    color: 'ink',
    paint: 'transparent',
    load: 0.95,
    end: 'stop',
  });
  stroke({
    path: [
      [x, sy(7.6, D), 0.7],
      [sx(Xc - side * 0.8, D), sy(7.95, D), 0.6],
      [head, sy(7.72, D), 0.5],
    ],
    brush: { type: 'round', width: w * 0.8 },
    color: 'ink',
    paint: 'transparent',
    load: 0.95,
  });
  stroke({
    path: [[head, sy(7.78, D), 0.6]],
    brush: { type: 'filbert', width: f * 0.4 },
    color: 'ink',
    paint: 'transparent',
    load: 0.9,
    angle: 0,
  });
  reflect(x, sy(0, D) + 2, Math.min(400, f * 5), w * 1.6, 'ink', 0.5);
}
for (const [X, D, side] of [
  [-5.2, 150, -1],
  [5.1, 120, 1],
  [-5.2, 120, -1],
  [5.1, 85, 1],
  [-5.2, 70, -1],
  [5.1, 46, 1],
  [-5.2, 38, -1],
  [5.1, 15, 1],
  [-5.2, 8, -1],
]) {
  lamp(X, D, side);
}

// The traffic signal at the near corner: a pole, a mast arm over the road, and two
// signal heads showing red. Each head is three upright strokes, the middle one
// lifting off where the red lamp is, which goes into the paper left there.
const SIG = { X: 5.2, D: 9.5 };
{
  const f = F / SIG.D;
  const px = sx(SIG.X, SIG.D);
  stroke({
    path: [
      [px, sy(0, SIG.D), 0.85],
      [px, sy(6.2, SIG.D), 0.8],
    ],
    brush: { type: 'round', width: 9 },
    color: 'ink',
    paint: 'transparent',
    load: 1,
    end: 'stop',
  });
  stroke({
    path: [
      [px, sy(6.15, SIG.D), 0.8],
      [sx(2, SIG.D), sy(6.2, SIG.D), 0.7],
      [sx(-0.6, SIG.D), sy(6.25, SIG.D), 0.5],
    ],
    brush: { type: 'round', width: 6 },
    color: 'ink',
    paint: 'transparent',
    load: 1,
    end: 'taper',
  });
  for (const X of [2.4, 0.3]) {
    const x = sx(X, SIG.D);
    const ly = sy(5.83, SIG.D);
    const top = sy(6.15, SIG.D);
    const bottom = sy(5.0, SIG.D);
    const cw = 0.12 * f;
    for (const k of [-1, 0, 1]) {
      const path = [];
      for (let y = top; y <= bottom; y += 3)
        path.push([x + k * cw, y, k === 0 && Math.abs(y - ly) < cw * 0.9 ? 0 : 0.85]);
      stroke({
        path,
        brush: { type: 'flat', width: cw * 1.15, streak: 0 },
        color: 'ink',
        paint: 'transparent',
        load: 1,
        end: 'stop',
      });
    }
    stroke({
      path: [[x, ly]],
      brush: { type: 'round', width: cw * 1.5 },
      color: 'signalRed',
      paint: 'transparent',
      load: 1,
    });
    stroke({
      path: [[x, ly]],
      brush: { type: 'soft', width: cw * 9 },
      color: 'signalRed',
      paint: 'transparent',
      thinner: 0.8,
      load: 0.75,
    });
  }
}

/**
 * A walker under an umbrella, the way a watercolorist puts a figure in the rain: one
 * stroke for the coat, wide at the shoulders and narrowing to the hem; two quick
 * flicks for the legs, one longer, mid-stride, their feet lost in the wet; a touch for
 * the head; and the canopy as one stroke swept back and forth across its dome, with a
 * crisp dark rim, the edge the eye finds. The reflection goes down into the road.
 */
function walker(X, D, canopy, stride) {
  const f = F / D;
  const x = sx(X, D);
  const foot = sy(0, D);
  const lean = rand(-0.03, 0.03) * f;
  const hem = foot - f * 0.62;
  const shoulder = foot - f * 1.45;
  // the legs: quick, tapering to nothing at the wet pavement
  for (const s of [-1, 1]) {
    const reach = s === Math.sign(stride) ? 1 : 0.7;
    stroke({
      path: [
        [x + s * f * 0.05, hem + f * 0.02, 0.9],
        [x + s * stride * f * 0.07 * reach, foot - f * 0.06 * (1 - reach), 0.35],
      ],
      brush: { type: 'round', width: Math.max(1.4, f * 0.1) },
      color: 'ink',
      paint: 'transparent',
      load: 0.95,
      end: 'taper',
    });
  }
  // the coat: shoulders down to the hem, pressed hard at the top
  stroke({
    path: [
      [x + lean, shoulder, 1],
      [x + lean * 0.5 + f * 0.02, shoulder + (hem - shoulder) * 0.5, 0.85],
      [x + rand(-0.02, 0.02) * f, hem + f * 0.04, 0.55],
    ],
    brush: { type: 'round', width: f * 0.42, streak: 0, splay: 0 },
    color: 'coat',
    paint: 'transparent',
    load: 0.95,
    end: 'taper',
  });
  // the head, half under the canopy
  stroke({
    path: [[x + lean, shoulder - f * 0.13, 0.8]],
    brush: { type: 'round', width: f * 0.2 },
    color: 'ink',
    paint: 'transparent',
    load: 0.9,
  });
  // the handle, then the canopy over it
  const cx = x + lean + f * 0.05;
  const crown = foot - f * 2.2;
  const rim = foot - f * 1.82;
  const R = f * 0.6;
  stroke({
    path: [
      [cx, shoulder + f * 0.25],
      [cx, rim],
    ],
    brush: { type: 'round', width: Math.max(1, f * 0.025) },
    color: 'ink',
    paint: 'transparent',
    load: 0.9,
  });
  fill(
    (y) => {
      const t = clamp01((y - crown) / (rim - crown));
      const half = R * Math.sqrt(Math.max(0.04, 1 - (1 - t) ** 2));
      return [cx - half, cx + half];
    },
    crown,
    rim + f * 0.03,
    Math.max(1.5, Math.min(5, (rim - crown) / 4)),
    canopy,
  );
  // the rim: dark and crisp, dipping between the rib tips
  const rimPath = [];
  for (let k = 0; k <= 8; k++) {
    const u = k / 8;
    rimPath.push([
      cx - R + 2 * R * u,
      rim + f * 0.03 * Math.sin(Math.PI * u) + (k % 2 ? f * 0.02 : 0),
    ]);
  }
  stroke({
    path: rimPath,
    brush: { type: 'round', width: Math.max(1.2, f * 0.045) },
    color: 'ink',
    paint: 'transparent',
    load: 0.9,
    end: 'taper',
  });
  stroke({
    path: [
      [cx, crown],
      [cx, crown - f * 0.1],
    ],
    brush: { type: 'round', width: Math.max(1, f * 0.03) },
    color: 'ink',
    paint: 'transparent',
    load: 0.9,
  });
  reflect(x, foot + 2, f * 1.3, f * 0.3, 'coat', 0.4);
  reflect(cx, foot + f * 0.7, f * 1.2, f * 0.6, canopy, 0.5);
  drag(x, foot, f * 2.2, f * 0.5);
}

walker(5.6, 60, 'ink', 0.6);
walker(-6.0, 42, 'ink', 0.5);
walker(6.1, 26, 'coat', 0.7);
walker(-6.2, 17, 'ink', 0.8);
walker(-5.5, 15.5, 'coat', -0.6);
walker(5.8, 12, 'ink', 0.5);
walker(-1.2, 8, 'umbrellaRed', 0.9);

dry();

/**
 * Passage 6: the night coming down, and the rain.
 *
 * Last, over everything dry: a blue-violet glaze from a big soft brush settles into
 * the corners, heaviest at the tops of the near walls and the bottom of the picture,
 * so the light pools in the middle of the avenue where the eye should go. The lamps
 * and headlights get a warm breath of halo, and the rain itself is drawn as fine
 * slanting threads, thinned almost to nothing, falling across the whole street.
 */

const W = canvas.width;
const H = canvas.height;
const VP = { x: 630, y: 780 };
const EYE = 5;
const F = 1000;
const sx = (X, D) => VP.x + (X * F) / D;
const sy = (Z, D) => VP.y + ((EYE - Z) * F) / D;
const clamp01 = (v) => Math.min(1, Math.max(0, v));

palette('nightVeil', mix(['payne', 1], ['ultra', 0.45], ['crimson', 0.4]));
palette('rain', mix(['payne', 1], ['ultra', 0.2], ['water', 1.5]));
palette('halo', mix(['gamboge', 1.5], ['ochre', 0.5], ['water', 4]));

/** Steam from the stack (as in passage 1): the glaze leaves it alone. */
const STACK = { x: sx(-3, 13), y: sy(2.4, 13) };
function steam(x, y) {
  const t = (STACK.y - y) / 420;
  if (t < -0.02 || t > 1.15) return 0;
  const u = Math.max(0, t);
  const cx = STACK.x - 150 * u ** 1.3 + 22 * noise(u * 3, 4.1);
  const half = 14 + 120 * u ** 0.8;
  const d = Math.abs(x - cx) / half;
  const n = 0.75 + 0.35 * noise(x / 40, y / 55);
  return clamp01((1 - d * d) * n * (1 - clamp01((t - 0.55) / 0.6)) * 1.25);
}

/** How far a point is from the light in the middle of the avenue, 0 there to 1 in the corners. */
function dark(x, y) {
  const dx = (x - VP.x) / (W * 0.55);
  const dy = y < VP.y ? (VP.y - y) / VP.y : (y - VP.y) / (H - VP.y);
  return clamp01(Math.hypot(dx * 1.1, dy * 0.8) - 0.35);
}

/** The glaze's three dishes: strong for the corners, medium between, pale nearest the light. */
const DISH = { strong: 0.62, medium: 0.76, pale: 0.9 };

// The night glaze: long soft sweeps at an even pressure, each from the dish for how
// far it lies from the light, the edges between dishes left ragged; none goes into
// the middle of the avenue.
brush('veil', { type: 'soft', width: 170, reservoir: 6 });
for (let y = -40; y < H + 60; y += 55) {
  for (let x = -120; x < W + 60; x += rand(200, 300)) {
    const len = rand(260, 380);
    const tilt = rand(-20, 20);
    const d = dark(x + len / 2, y + tilt / 2);
    if (d < 0.12 || steam(x + len / 2, y) > 0.2) continue;
    const k = d + 0.12 * noise(x / 260, y / 200) + rand(-0.05, 0.05);
    stroke({
      path: [
        [x, y + rand(-6, 6)],
        [x + len / 2, y + tilt / 2 + rand(-6, 6)],
        [x + len, y + tilt],
      ],
      brush: 'veil',
      color: 'nightVeil',
      paint: 'glaze',
      thinner: k > 0.62 ? DISH.strong : k > 0.36 ? DISH.medium : DISH.pale,
      load: 0.85,
      pressure: 0.75,
    });
  }
}

// Warm halos around the headlights and the lamps: a breath of thin gold.
for (const [X, D, Z] of [
  [-3.1, 24, 0.65],
  [-1.7, 24, 0.65],
  [-3.6, 60, 0.65],
  [-1.6, 60, 0.65],
  [-3.6, 38, 7.5],
  [3.5, 46, 7.5],
  [-3.6, 70, 7.5],
  [3.5, 85, 7.5],
  [3.5, 15, 7.5],
]) {
  stroke({
    path: [[sx(X, D), sy(Z, D)]],
    brush: { type: 'soft', width: Math.max(14, (2.2 * F) / D) },
    color: 'halo',
    paint: 'transparent',
    thinner: 0.8,
    load: 0.7,
  });
}

// The rain: fine threads, all slanting the same way, a little longer near the eye.
for (let k = 0; k < 520; k++) {
  const x = rand(-40, W + 40);
  const y = rand(-20, H);
  const len = 24 + (y / H) * 50 + rand(0, 30);
  stroke({
    path: [
      [x, y, 0.5],
      [x + len * 0.2, y + len, 0.35],
    ],
    brush: { type: 'round', width: rand(1, 1.8) },
    color: 'rain',
    paint: 'glaze',
    thinner: 0.8,
    load: 0.8,
    end: 'flick',
  });
}

dry();
